/**
 * Domain model.
 *
 * The shape below is deliberately *normalised* (exercises / sessions / set
 * entries are separate collections joined by id) so the exact same model maps
 * 1:1 onto the SQLite schema in `db/schema.sql`. Swapping the localStorage
 * driver for SQLite later means reimplementing `lib/storage.ts` only — no
 * component and no selector has to change.
 */

/** Opaque identifier. Generated by `createId()` in `lib/utils.ts`. */
export type Id = string;

/** Calendar day in `YYYY-MM-DD`, always in the user's local timezone. */
export type IsoDate = string;

export const MUSCLE_GROUPS = [
  "chest",
  "back",
  "shoulders",
  "biceps",
  "triceps",
  "quads",
  "hamstrings",
  "glutes",
  "calves",
  "core",
] as const;

export type MuscleGroup = (typeof MUSCLE_GROUPS)[number];

export const MUSCLE_GROUP_LABELS: Record<MuscleGroup, string> = {
  chest: "الصدر",
  back: "الظهر",
  shoulders: "الأكتاف",
  biceps: "الباي",
  triceps: "التراي",
  quads: "أمامية الفخذ",
  hamstrings: "خلفية الفخذ",
  glutes: "الجلوت",
  calves: "البطة",
  core: "البطن",
};

/**
 * Weekly working-set landmarks per muscle group.
 *
 * `mev` is the least weekly volume that still grows the muscle, `mav` the middle
 * of the productive band, `mrv` the ceiling past which extra sets buy fatigue
 * instead of growth. These are the published hypertrophy ranges, not something
 * derived from the user's own log — they are the yardstick the log is measured
 * against, which is exactly why they are constants and not settings: a target
 * that moves with the behaviour it measures cannot tell the user anything.
 */
export const MUSCLE_LANDMARKS: Record<
  MuscleGroup,
  { mev: number; mav: number; mrv: number }
> = {
  chest: { mev: 10, mav: 18, mrv: 22 },
  back: { mev: 10, mav: 20, mrv: 25 },
  shoulders: { mev: 8, mav: 18, mrv: 26 },
  biceps: { mev: 8, mav: 16, mrv: 20 },
  triceps: { mev: 6, mav: 14, mrv: 18 },
  quads: { mev: 8, mav: 16, mrv: 20 },
  hamstrings: { mev: 6, mav: 14, mrv: 20 },
  glutes: { mev: 4, mav: 12, mrv: 16 },
  calves: { mev: 8, mav: 16, mrv: 20 },
  core: { mev: 6, mav: 16, mrv: 25 },
};

export interface Exercise {
  id: Id;
  name: string;
  muscleGroup: MuscleGroup;
  /** Free text: "machine", "cable", "barbell"… used for grouping only. */
  equipment: string;
  createdAt: number;
  archived: boolean;
  /**
   * The machine's own settings — seat notch, pin hole, pad height.
   *
   * On a machine-based program this is the most perishable knowledge in a
   * session: the load means nothing if the seat moved, because the range of
   * motion moved with it. Free text, because no two gyms label a machine alike.
   */
  setup: string;
  /** Target rep range for double progression. `null` → use the global setting. */
  repMin: number | null;
  repMax: number | null;
  /** Smallest load step this machine offers, kg. `null` → the global setting. */
  incrementKg: number | null;
  /** Default rest between sets, seconds. `null` → the global setting. */
  restSeconds: number | null;
}

/** One template day of the training split (Push / Pull / Legs / …). */
export interface ProgramDay {
  id: Id;
  /** Stable machine name used in URLs and defaults: `push`, `pull`, … */
  slug: string;
  /** Latin display name, e.g. "Push". */
  name: string;
  /** Arabic subtitle describing the target muscles. */
  focus: string;
  exerciseIds: Id[];
  order: number;
}

/** A training day that actually happened. */
export interface Session {
  id: Id;
  date: IsoDate;
  /** Which template day it was based on. `null` for an ad-hoc session. */
  programDayId: Id | null;
  note: string;
  createdAt: number;
  updatedAt: number;
  /**
   * 1–5 self-rated readiness logged before training. `null` when unrated.
   *
   * Session *length* is deliberately not stored beside it: it is derived from
   * the first and last set of the day in `metrics.ts`, because a stored duration
   * depends on the user remembering to stop a stopwatch, and a forgotten
   * stopwatch reports a six-hour session — worse than no number at all.
   */
  readiness: number | null;
}

/** A single logged set. This is the atomic fact the whole app is built on. */
export interface SetEntry {
  id: Id;
  sessionId: Id;
  exerciseId: Id;
  /** 1-based position of the set inside the session, per exercise. */
  setIndex: number;
  /** Always stored in kilograms; display units are a presentation concern. */
  weightKg: number;
  reps: number;
  /** Rate of perceived exertion, 1–10. Optional. */
  rpe: number | null;
  /** Warm-up sets are excluded from volume and PR maths. */
  isWarmup: boolean;
  createdAt: number;
}

export interface NutritionLog {
  date: IsoDate;
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
}

/**
 * A body check-in. Every field is nullable on purpose: someone who steps on the
 * scale daily but reaches for a tape measure once a month must not be forced to
 * invent the numbers he did not take, and a stored zero would poison every
 * average that reads the column.
 */
export interface BodyMetric {
  date: IsoDate;
  weightKg: number | null;
  waistCm: number | null;
  chestCm: number | null;
  armCm: number | null;
  thighCm: number | null;
  shoulderCm: number | null;
  note: string;
}

/**
 * A day's health markers — the half of the picture a barbell cannot see.
 *
 * These sit apart from `BodyMetric` because they are measured on a different
 * clock: a tape measure comes out once a fortnight, whereas sleep and steps are
 * a daily reading whose *streak* is the point. Keeping them in one record would
 * mean a body check-in and a night's sleep sharing a row, and the sparse one
 * would drag the dense one's averages around.
 *
 * Every field is nullable, for the same reason `BodyMetric`'s are: a stored
 * zero is a claim ("I slept 0 hours"), and it would poison every mean that
 * reads the column. Absent must stay distinguishable from none.
 */
export interface HealthLog {
  date: IsoDate;
  /**
   * Hours slept. The single biggest lever here: it moves recovery, appetite,
   * and how hard a session feels, and it is the one the user already suspects.
   */
  sleepHours: number | null;
  /**
   * When the lights went out, "HH:MM" on a 24-hour clock.
   *
   * Logged beside the duration and not derived from it, because the two fail
   * differently — seven hours starting at 02:00 is not seven hours starting at
   * 23:00, and only the bedtime shows a drift that is still invisible in the
   * total.
   */
  bedtime: string | null;
  /** Daily steps: everything burnt outside the gym, which is most of it. */
  steps: number | null;
  waterMl: number | null;
  /** Resting heart rate, bpm — the cheapest conditioning marker there is. */
  restingHr: number | null;
  note: string;
}

export const HEALTH_FIELDS = [
  "sleepHours",
  "steps",
  "waterMl",
  "restingHr",
] as const;

export type HealthField = (typeof HEALTH_FIELDS)[number];

export const HEALTH_FIELD_META: Record<
  HealthField,
  { label: string; unit: string; min: number; max: number; step: number }
> = {
  sleepHours: { label: "النوم", unit: "ساعة", min: 0, max: 16, step: 0.5 },
  steps: { label: "الخطوات", unit: "خطوة", min: 0, max: 100_000, step: 100 },
  waterMl: { label: "الماء", unit: "مل", min: 0, max: 10_000, step: 250 },
  restingHr: { label: "نبض الراحة", unit: "ن/د", min: 25, max: 150, step: 1 },
};

export const BODY_FIELDS = [
  "weightKg",
  "waistCm",
  "chestCm",
  "armCm",
  "thighCm",
  "shoulderCm",
] as const;

export type BodyField = (typeof BODY_FIELDS)[number];

export const BODY_FIELD_META: Record<
  BodyField,
  { label: string; unit: string; min: number; max: number }
> = {
  weightKg: { label: "الوزن", unit: "كجم", min: 20, max: 400 },
  waistCm: { label: "الخصر", unit: "سم", min: 40, max: 200 },
  chestCm: { label: "الصدر", unit: "سم", min: 50, max: 200 },
  armCm: { label: "البايسبس", unit: "سم", min: 15, max: 80 },
  thighCm: { label: "الفخذ", unit: "سم", min: 25, max: 120 },
  shoulderCm: { label: "الأكتاف", unit: "سم", min: 60, max: 250 },
};

export type WeightUnit = "kg" | "lb";

export interface Settings {
  unit: WeightUnit;
  /** Sessions per week the user is aiming for. Drives the consistency ring. */
  weeklyGoal: number;
  bodyWeightKg: number | null;
  targets: {
    kcal: number;
    protein: number;
    carbs: number;
    fat: number;
  };
  /** Default rest between sets, seconds. A per-exercise value overrides it. */
  restSeconds: number;
  /** The rep window double progression works inside. */
  repMin: number;
  repMax: number;
  /** Default load step when a machine has no value of its own, kg. */
  incrementKg: number;
  /** Chime when the rest timer ends. */
  restSound: boolean;
  /** Buzz when the rest timer ends (Android; iOS Safari ignores it). */
  restVibrate: boolean;
  /** Start the rest timer by itself the moment a set is saved. */
  restAutoStart: boolean;
  /**
   * Standing height, cm.
   *
   * Only here to make waist-to-height computable. That ratio is the one body
   * number on this screen with a published threshold behind it — keep the waist
   * under half your height — which is worth more than a weight that cannot tell
   * muscle from fat.
   */
  heightCm: number | null;
  /** Daily health targets. Same role as `targets` does for macros. */
  healthTargets: {
    sleepHours: number;
    steps: number;
    waterMl: number;
  };
}

/** The entire persisted document. One row, versioned, atomically written. */
export interface Database {
  version: number;
  exercises: Exercise[];
  programDays: ProgramDay[];
  sessions: Session[];
  setEntries: SetEntry[];
  /**
   * Sessions of every discipline that is not the gym — boxing, riding,
   * running. Gym days stay in `sessions` + `setEntries`, because that is the
   * normalised shape the overload engine and the muscle-landmark maths read,
   * and flattening a lift into one row would throw away the per-set facts
   * they are built on. One sport, one shape; `SPORTS_CONFIG` says which.
   */
  athleticSessions: AthleticSession[];
  /** Explicit gym check-ins, including rest-day cardio. Keyed by date. */
  attendance: Record<IsoDate, boolean>;
  nutrition: Record<IsoDate, NutritionLog>;
  /** Body check-ins, keyed by date. */
  bodyMetrics: Record<IsoDate, BodyMetric>;
  /** Daily health markers — sleep, steps, water, resting pulse. */
  health: Record<IsoDate, HealthLog>;
  settings: Settings;
  updatedAt: number;
}

/* ------------------------------------------------------------------ */
/* Derived, read-only view models used by the dashboard                */
/* ------------------------------------------------------------------ */

/** One point on an exercise's progression curve — one session, one exercise. */
export interface ExerciseProgressPoint {
  date: IsoDate;
  sessionId: Id;
  /** Heaviest working weight lifted that day. */
  topWeightKg: number;
  /** Reps achieved on the top set, for context on the tooltip. */
  topSetReps: number;
  /** Estimated 1-rep-max (Epley) of the best set that day. */
  estimated1rm: number;
  /** Σ weight × reps across working sets. */
  volumeKg: number;
  totalReps: number;
  /** True when `topWeightKg` beat every previous session. */
  isPr: boolean;
}

export interface VolumePoint {
  date: IsoDate;
  sessionId: Id;
  volumeKg: number;
  setCount: number;
  label: string;
}

export interface MuscleGroupVolume {
  group: MuscleGroup;
  label: string;
  volumeKg: number;
  setCount: number;
  share: number;
}

/** Where a muscle's weekly set count falls against its landmarks. */
export type VolumeStatus = "none" | "under" | "optimal" | "peak" | "over";

export interface MuscleVolumeRow {
  group: MuscleGroup;
  label: string;
  /** Working sets in the trailing week. */
  sets: number;
  mev: number;
  mav: number;
  mrv: number;
  status: VolumeStatus;
  /** One short Arabic line: what to do about it. */
  advice: string;
}

export interface PersonalRecord {
  exerciseId: Id;
  exerciseName: string;
  date: IsoDate;
  weightKg: number;
  reps: number;
  estimated1rm: number;
  /** Improvement over the previous best, in kg. `null` for a first record. */
  gainKg: number | null;
}

export interface WeeklyBucket {
  /** ISO date of the Saturday that opens the week (week starts Saturday). */
  weekStart: IsoDate;
  label: string;
  sessions: number;
  volumeKg: number;
  attended: number;
}

/** Why a target was chosen — drives the one-line explanation printed under it. */
export type OverloadReason =
  | "first"
  | "add-reps"
  | "increase-weight"
  | "hold"
  | "repeat";

/** The next set the app is asking for, and the reasoning behind it. */
export interface OverloadTarget {
  exerciseId: Id;
  weightKg: number;
  reps: number;
  reason: OverloadReason;
  /** Session the target was derived from. `null` on a first-ever attempt. */
  basedOn: IsoDate | null;
  repMin: number;
  repMax: number;
  incrementKg: number;
}

/** A lift that has stopped moving — the change-something signal. */
export interface StallRow {
  exerciseId: Id;
  exerciseName: string;
  /** Sessions logged since the last estimated-1RM improvement. */
  sessionsStalled: number;
  daysSinceBest: number;
  best1rm: number;
  latest1rm: number;
  lastDate: IsoDate;
}

/** One body check-in, ready to chart: the raw value and its smoothed twin. */
export interface BodyPoint {
  date: IsoDate;
  label: string;
  value: number;
  /** Trailing 7-day mean — the line that should actually be read. */
  average: number;
}

/* ------------------------------------------------------------------ */
/* Multi-sport: the disciplines beside the gym                         */
/* ------------------------------------------------------------------ */

export const SPORT_IDS = ["gym", "boxing", "equestrian", "running"] as const;

export type SportId = (typeof SPORT_IDS)[number];

/**
 * How a session of a discipline is logged.
 *
 * The live HUD branches on this and never on a sport id, which is the whole
 * reason a new discipline is a config change rather than a refactor: four
 * sports already share three surfaces.
 */
export type SportEngine = "sets" | "rounds" | "stopwatch" | "distance";

/** Which way is better for a record — heavier/longer/further, or faster. */
export type RecordDirection = "max" | "min";

export interface SportField {
  key: AthleticField;
  label: string;
  /** Shown beside the figure, never inside it. Empty for unitless. */
  unit: string;
  step: number;
  min: number;
  max: number;
}

export interface SportMetric {
  key: string;
  label: string;
  unit: string;
  /** Pure: one session row in, a number out. No clock, no DOM. */
  calc: (session: AthleticSession) => number;
  /** For a number that is not read as a number — pace is "5:22", not 5.37. */
  format?: (value: number) => string;
}

export interface SportRecordKind {
  key: string;
  label: string;
  better: RecordDirection;
  unit: string;
  format?: (value: number) => string;
}

export interface SportTimer {
  mode: "rest" | "round" | "stopwatch";
  /** Work interval, seconds. 0 when the sport has none. */
  work: number;
  /** Rest interval, seconds. */
  rest: number;
  /** Planned rounds. 0 when the sport is not round-based. */
  rounds: number;
  /** Whether the clock starts itself when the session opens. */
  autoStart: boolean;
}

/**
 * Everything that makes a discipline a discipline.
 *
 * Nothing in here is optional detail: `fields` builds the inputs, `metrics`
 * builds the HUD's stat strip, `records` builds the trophy shelf, and
 * `strain` + `weeklyTarget` build the weekly radar. Fill all of them and the
 * sport is supported everywhere by construction; leave one out and it is
 * missing from exactly one screen, silently.
 */
export interface SportConfig {
  id: SportId;
  /** Latin name, set in the condensed display face. */
  name: string;
  /** Arabic label — the shipping UI reads this one. */
  nameAr: string;
  /** Key into `SPORT_ICONS` in `components/session/sport-icon.tsx`. */
  icon: SportId;
  /** The CSS custom property this sport is drawn in, e.g. "--sport-gym". */
  accentVar: string;
  engine: SportEngine;
  /** Sessions a week the radar measures this sport's ring against. */
  weeklyTarget: number;
  timer: SportTimer;
  /** Session flavours (bag / pads / sparring). Tags, never logic. */
  modes: Array<{ id: string; label: string }>;
  fields: SportField[];
  metrics: SportMetric[];
  records: SportRecordKind[];
  /** One session → a 0–100 load, so a ride and a lift share one week. */
  strain: (session: AthleticSession) => number;
}

export const ATHLETIC_FIELDS = [
  "rounds",
  "roundSeconds",
  "intensity",
  "minutes",
  "km",
  "avgHr",
] as const;

export type AthleticField = (typeof ATHLETIC_FIELDS)[number];

/**
 * One logged session of a non-gym discipline.
 *
 * Every measurement is nullable, for the same reason `BodyMetric`'s are: a
 * stored zero is a claim. "0 bpm" and "I did not wear a strap" are different
 * facts, and only the second one can be left out of an average.
 *
 * `endedAt` being null is what makes a session *live* — there is exactly one
 * such row at a time, and the HUD renders it.
 */
export interface AthleticSession {
  id: Id;
  sport: SportId;
  date: IsoDate;
  /** One of the sport's own `modes`. Empty string when none was chosen. */
  mode: string;
  startedAt: number;
  /** null while the session is still running. */
  endedAt: number | null;
  /** Rounds actually completed. Boxing and any other round-based sport. */
  rounds: number | null;
  /** Length of one round, seconds. */
  roundSeconds: number | null;
  /** Self-rated 1–10. The round-based answer to RPE. */
  intensity: number | null;
  minutes: number | null;
  km: number | null;
  avgHr: number | null;
  /** Equestrian: which gaits the ride actually used. */
  gaits: string[];
  /** Equestrian: which horse. Free text — no two yards name them alike. */
  horse: string;
  note: string;
}

/** One discipline's week, measured against its own target. */
export interface SportLoadRow {
  sport: SportId;
  name: string;
  nameAr: string;
  accentVar: string;
  sessions: number;
  target: number;
  strain: number;
  /** 0–1, clamped. */
  progress: number;
}

/** A record, already resolved to the session that set it. */
export interface AthleticRecord {
  sport: SportId;
  sportName: string;
  accentVar: string;
  key: string;
  label: string;
  unit: string;
  value: number;
  display: string;
  date: IsoDate;
  /** True when this record was set by the session that just finished. */
  fresh: boolean;
}
